+static PyObject* python_set_single_allocation(PyObject* self, PyObject* args) {
+  int enabled = 0;
+  if (!PyArg_ParseTuple(args, "p", &enabled)) {
+    return nullptr;
+  }
+  bool previous = g_single_allocation;
+  g_single_allocation = enabled != 0;
+  return PyBool_FromLong(previous);
+}
